import Foundation

/// A running host the CLI can talk to: one per browser profile that has the
/// extension loaded.
public struct BrowserEndpoint: Encodable {
    public let browser: String
    /// The host process's pid, which is also what the socket name carries.
    public let pid: pid_t
    public let socket: String
    public let extensionVersion: String?
    public let hostVersion: String?
    public let since: String?
    /// Generated by the extension on first run and kept in its storage; nil
    /// when the extension predates 0.10.
    public let instanceId: String?
    public let label: String?
    public let userDataDir: String?
    /// `Default`, `Profile 2`, …; nil when the host could not prove which.
    public let profileDir: String?
    public let profileName: String?
    /// False for a relay whose extension has not checked in lately (Safari):
    /// it exists, but a request would only wait. Chrome hosts are always
    /// ready — the browser spawns them for a live extension.
    public var ready: Bool = true

    public init(browser: String, pid: pid_t, socket: String, extensionVersion: String? = nil, hostVersion: String? = nil, since: String? = nil,
                instanceId: String? = nil, label: String? = nil, userDataDir: String? = nil, profileDir: String? = nil, profileName: String? = nil,
                ready: Bool = true) {
        self.browser = browser
        self.pid = pid
        self.socket = socket
        self.extensionVersion = extensionVersion
        self.hostVersion = hostVersion
        self.since = since
        self.instanceId = instanceId
        self.label = label
        self.userDataDir = userDataDir
        self.profileDir = profileDir
        self.profileName = profileName
        self.ready = ready
    }

    /// Built from the host's answer to `hello`; the socket name is the
    /// fallback for the browser name.
    public static func fromHello(_ result: [String: Any], browser fallbackBrowser: String, pid: pid_t, socket: String) -> BrowserEndpoint {
        func text(_ key: String) -> String? { (result[key] as? String).flatMap { $0.isEmpty ? nil : $0 } }
        // macOS 27's System Policy sandbox denies a host that Chrome spawned
        // any read under Chrome's own data directory (`deny file-read-data
        // …/Google/Chrome/Local State` in the sandbox log), so the host answers
        // with the user data dir only. The CLI runs under the agent's host and
        // usually may read it, so it finishes the inference here.
        var profileDir = text("profileDir")
        var profileName = text("profileName")
        if let root = text("userDataDir").map({ URL(fileURLWithPath: $0, isDirectory: true) }) {
            if profileDir == nil, let id = text("instanceId") {
                profileDir = ProfileLocator.profileDirectory(instanceID: id, extensionID: text("extensionId") ?? BrowserBridge.extensionID, userDataDir: root)
            }
            if profileName == nil, let profileDir {
                profileName = ProfileLocator.profileName(userDataDir: root, profileDir: profileDir)
            }
        }
        return BrowserEndpoint(
            browser: text("browser") ?? fallbackBrowser,
            pid: pid,
            socket: socket,
            extensionVersion: text("extensionVersion"),
            hostVersion: text("hostVersion"),
            since: text("since"),
            instanceId: text("instanceId"),
            label: text("label"),
            userDataDir: text("userDataDir"),
            profileDir: profileDir,
            profileName: profileName,
            ready: result["ready"] as? Bool ?? true
        )
    }

    /// `chrome (pid 123, profile "Profile 2" BunnyGleam, label shop)`.
    public var summary: String {
        var bits = ["pid \(pid)"]
        if let profileDir {
            bits.append("profile \"\(profileDir)\"" + (profileName.map { " \($0)" } ?? ""))
        } else if instanceId != nil {
            bits.append("profile unknown")
        }
        if let label { bits.append("label \(label)") }
        if let instanceId { bits.append("instance \(instanceId)") }
        return "\(browser) (\(bits.joined(separator: ", ")))"
    }

    private enum CodingKeys: String, CodingKey {
        case browser, pid, socket, extensionVersion, hostVersion, since, ready, instanceId, label, userDataDir, profileDir, profileName
    }

    /// Unknown identity fields are written as null rather than dropped, so a
    /// reader can tell "not known" from "not reported by this version".
    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(browser, forKey: .browser)
        try container.encode(pid, forKey: .pid)
        try container.encode(socket, forKey: .socket)
        try container.encode(extensionVersion, forKey: .extensionVersion)
        try container.encode(hostVersion, forKey: .hostVersion)
        try container.encode(since, forKey: .since)
        try container.encode(ready, forKey: .ready)
        try container.encode(instanceId, forKey: .instanceId)
        try container.encode(label, forKey: .label)
        try container.encode(userDataDir, forKey: .userDataDir)
        try container.encode(profileDir, forKey: .profileDir)
        try container.encode(profileName, forKey: .profileName)
    }
}

/// The CLI's side of the bridge: finds hosts, picks one, sends requests.
public final class BrowserClient {
    public let endpoint: BrowserEndpoint

    public init(endpoint: BrowserEndpoint) {
        self.endpoint = endpoint
    }

    // MARK: - Discovery

    /// Every host that answers on its socket. Sockets nobody answers on are
    /// left over from a host that died and are removed on the way past.
    public static func discover() -> [BrowserEndpoint] {
        let directory = BrowserBridge.socketDirectory
        guard let names = try? FileManager.default.contentsOfDirectory(atPath: directory.path) else { return [] }
        var endpoints: [BrowserEndpoint] = []
        for name in names.sorted() {
            guard let parsed = BrowserBridge.parseSocketName(name) else { continue }
            let path = directory.appendingPathComponent(name).path
            guard let fd = connect(path: path) else {
                if kill(parsed.pid, 0) != 0 && errno == ESRCH { unlink(path) }
                continue
            }
            defer { close(fd) }
            guard let reply = try? roundTrip(fd: fd, request: ["id": 0, "method": "hello", "params": [:], "timeoutMs": 2000], timeoutSeconds: 3),
                  let result = reply["result"] as? [String: Any] else { continue }
            endpoints.append(BrowserEndpoint.fromHello(result, browser: parsed.browser, pid: parsed.pid, socket: path))
        }
        return endpoints
    }

    /// Picks the connection for a command; see `BrowserSelection.choose`.
    public static func select(browser: String?, profile: String?) throws -> BrowserClient {
        // Safari's relay is started on demand, by the first command that asks for Safari.
        if SafariBridge.isSafariSelector(browser) && !discover().contains(where: { $0.browser == SafariBridge.browserName }) {
            try SafariRelay.ensureRunning()
        }
        return BrowserClient(endpoint: try BrowserSelection.choose(from: discover(), browser: browser, profile: profile))
    }

    // MARK: - Requests

    /// Sends one request and returns the extension's result. Errors the
    /// extension reports come back as AmcuError with its code and next steps.
    public func request(_ method: String, params: [String: Any] = [:], timeout: TimeInterval = 30) throws -> JSONValue {
        guard let fd = BrowserClient.connect(path: endpoint.socket) else {
            throw AmcuError(.bridgeUnavailable, "the \(endpoint.browser) host went away", nextSteps: [
                "The browser or the extension was probably closed or reloaded; run `amcu browser tabs` to reconnect."
            ])
        }
        defer { close(fd) }
        let timeoutMs = Int(timeout * 1000)
        let request: [String: Any] = ["id": 1, "method": method, "params": params, "timeoutMs": timeoutMs]
        let reply = try BrowserClient.roundTrip(fd: fd, request: request, timeoutSeconds: timeout + 5)
        if reply["ok"] as? Bool == true {
            return JSONValue(reply["result"])
        }
        let error = reply["error"] as? [String: Any] ?? [:]
        throw BrowserBridge.error(
            fromCode: error["code"] as? String ?? "page_error",
            message: error["message"] as? String ?? "the extension reported an error without a message",
            nextSteps: error["nextSteps"] as? [String] ?? []
        )
    }

    // MARK: - Plumbing

    private static func connect(path: String) -> Int32? {
        let fd = socket(AF_UNIX, SOCK_STREAM, 0)
        guard fd >= 0 else { return nil }
        var one: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, socklen_t(MemoryLayout<Int32>.size))
        var address = sockaddr_un()
        address.sun_family = sa_family_t(AF_UNIX)
        let bytes = Array(path.utf8CString)
        guard bytes.count <= MemoryLayout.size(ofValue: address.sun_path) else { close(fd); return nil }
        withUnsafeMutablePointer(to: &address.sun_path) { pointer in
            pointer.withMemoryRebound(to: CChar.self, capacity: bytes.count) { dest in
                for (index, byte) in bytes.enumerated() { dest[index] = byte }
            }
        }
        let result = withUnsafePointer(to: &address) { pointer in
            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                Darwin.connect(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size))
            }
        }
        guard result == 0 else { close(fd); return nil }
        return fd
    }

    private static func roundTrip(fd: Int32, request: [String: Any], timeoutSeconds: TimeInterval) throws -> [String: Any] {
        var line = try JSONSerialization.data(withJSONObject: request)
        line.append(0x0A)
        var offset = 0
        let bytes = [UInt8](line)
        while offset < bytes.count {
            let written = bytes.withUnsafeBufferPointer { write(fd, $0.baseAddress! + offset, bytes.count - offset) }
            if written < 0 {
                if errno == EINTR { continue }
                throw AmcuError(.bridgeUnavailable, "could not write to the host socket: \(String(cString: strerror(errno)))")
            }
            offset += written
        }

        var timeout = timeval(tv_sec: Int(timeoutSeconds), tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
        // Replies are a single newline-terminated line; a screenshot can be
        // several megabytes, so only the freshly-read bytes are scanned for the
        // terminator rather than the whole growing buffer each pass.
        var buffer = Data()
        var chunk = [UInt8](repeating: 0, count: 1 << 16)
        var scanned = 0
        while true {
            let count = read(fd, &chunk, chunk.count)
            if count < 0 {
                if errno == EINTR { continue }
                if errno == EAGAIN || errno == EWOULDBLOCK {
                    throw AmcuError(.timeout, "the host did not answer within \(Int(timeoutSeconds))s", nextSteps: [
                        "Run `amcu browser doctor`; if the browser is fine, `amcu browser snapshot` shows the current state before you retry."
                    ])
                }
                throw AmcuError(.bridgeUnavailable, "read from the host socket failed: \(String(cString: strerror(errno)))")
            }
            if count == 0 {
                throw AmcuError(.bridgeUnavailable, "the host closed the connection", nextSteps: [
                    "The browser or the extension probably went away mid-request; run `amcu browser tabs` and retry."
                ])
            }
            let base = buffer.count
            buffer.append(chunk, count: count)
            if let newline = buffer[max(scanned, buffer.startIndex)...].firstIndex(of: 0x0A) {
                let payload = buffer.subdata(in: buffer.startIndex..<newline)
                guard let object = try? JSONSerialization.jsonObject(with: payload) as? [String: Any] else {
                    throw AmcuError(.bridgeUnavailable, "the host sent a malformed reply")
                }
                return object
            }
            scanned = base + count
        }
    }
}
